// Frequencies are horizontal: label in col A, values in B, C, D...
// Find whichever row contains a 'Frequencies' label, collect all numeric values from it.
const allItems = $input.all();
const freqs = [];

for (const item of allItems) {
  let vals = Object.values(item.json);
  // n8n sometimes wraps the whole row as a nested array under one key
  if (vals.length === 1 && Array.isArray(vals[0])) vals = vals[0];

  const hasLabel = vals.some(v => /freq/i.test(String(v ?? '')));
  if (!hasLabel) continue;

  for (const v of vals) {
    const mhz = parseFloat(String(v ?? '').trim());
    if (!isNaN(mhz)) freqs.push(mhz * 1e6);
  }
  break;
}

if (freqs.length === 0) {
  const sample = JSON.stringify(allItems[0]?.json ?? {});
  throw new Error('No frequencies row found. First row: ' + sample);
}
return [{ json: { frequencies_hz: freqs } }];

// Collect all frequency values from the first column of each row.
// ExtractFromFile with headerRow:false uses numeric keys (0, 1, 2, ...).
const freqs = [];
for (const item of $input.all()) {
  const val = item.json[0] ?? item.json[Object.keys(item.json)[0]];
  const num = parseFloat(String(val).trim());
  if (!isNaN(num)) freqs.push(num);
}
if (freqs.length === 0) throw new Error('No numeric frequencies found in Sheet1 column A');
return [{ json: { frequencies_hz: freqs } }];

// Build the append-results payload: all rows + timestamp in one request.
const allItems = $input.all();
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const timestamp = `${pad(now.getDate())}/${pad(now.getMonth()+1)}/${now.getFullYear()} | ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;

let results;
if (allItems.length === 1 && Array.isArray(allItems[0].json)) {
  results = allItems[0].json;
} else {
  results = allItems.map(i => i.json);
}

const rows = results.map(r => ({
  'Timestamp':  timestamp,
  'Freq (MHz)': r.freq_hz / 1e6,
  'R (Ohm)':    r.r_ohm,
  'X (Ohm)':    r.x_ohm,
  'L (nH)':     r.l_nh,
  'S11 (dB)':   r.s11_db,
}));

return [{ json: { file_path: 'C:/Users/yossefa/OneDrive - Arad Technologies Ltd/Documents/GitHub/rf-instrument-wrappers/n8n/Smith_Results.xlsx', sheet_name: 'Results', rows } }];

// The ENA endpoint returns an array; n8n wraps it as a single item.
// Build the write-results payload with current timestamp.
const raw = $input.first().json;
const results = Array.isArray(raw) ? raw : [raw];
const timestamp = new Date().toISOString();
return [{
  json: {
    file_path: "/files/Smith.xlsx",
    sheet_name: "Results",
    timestamp: timestamp,
    results: results
  }
}];
